namespace EmbyClient.App.Services;

/// <summary>Trusted installer code is generated by the client, never executed from a release archive.</summary>
internal static class ReleaseUpdateInstallerScript
{
    internal const string Content = """
    #requires -Version 5.1
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][string]$PlanPath)

    $ErrorActionPreference = 'Stop'
    Set-StrictMode -Version Latest
    $updateStage = [IO.Path]::GetFullPath($PSScriptRoot).TrimEnd('\')
    $updateLog = [IO.Path]::Combine($updateStage, 'install.log')
    $updatePreviousExecutable = $null
    $updateParentExited = $false
    $updateNewProcessCreated = $false
    $updateShortcutChanged = $false
    $updateShortcutBackup = $null
    $updateShortcutHash = $null
    $updateShortcutPath = $null
    $updateCancelPath = $null
    $updateParent = $null
    $updateWasCancelled = $false

    function Write-UpdateLog([string]$Message) {
        # Diagnostics must not interrupt process handoff or shortcut recovery.
        try {
            Assert-OrdinaryPath $updateLog
            [IO.File]::AppendAllText($updateLog, [DateTime]::UtcNow.ToString('O') + ' ' + $Message + [Environment]::NewLine,
                [Text.UTF8Encoding]::new($false))
        }
        catch { }
    }

    function Assert-OrdinaryPath([string]$Path) {
        $updateAncestor = [IO.Path]::GetFullPath($Path)
        while ($updateAncestor) {
            try {
                if (([IO.File]::GetAttributes($updateAncestor) -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
                    throw 'Update paths cannot traverse links or reparse points.'
                }
            }
            catch [IO.FileNotFoundException] { }
            catch [IO.DirectoryNotFoundException] { }
            $updateAncestor = [IO.Path]::GetDirectoryName($updateAncestor)
        }
    }

    function Get-UpdateHash([string]$Path) {
        Assert-OrdinaryPath $Path
        $updateHashStream = [IO.File]::OpenRead($Path)
        $updateHasher = [Security.Cryptography.SHA256]::Create()
        try { return [BitConverter]::ToString($updateHasher.ComputeHash($updateHashStream)).Replace('-', '').ToLowerInvariant() }
        finally { $updateHasher.Dispose(); $updateHashStream.Dispose() }
    }

    function Get-PayloadPath([string]$Root, [string]$RelativePath) {
        if (-not $RelativePath -or $RelativePath.Length -gt 240 -or $RelativePath.Contains('\') -or $RelativePath.StartsWith('/')) {
            throw 'A payload path is invalid.'
        }
        foreach ($updatePart in $RelativePath.Split('/')) {
            if (-not $updatePart -or $updatePart -eq '.' -or $updatePart -eq '..' -or $updatePart.EndsWith('.') -or $updatePart.EndsWith(' ')) {
                throw 'A payload path is unsafe.'
            }
            foreach ($updateCharacter in $updatePart.ToCharArray()) {
                if ([char]::IsControl($updateCharacter) -or '<>:"|?*'.Contains([string]$updateCharacter)) { throw 'A payload filename is unsafe.' }
            }
            $updateStem = $updatePart.Split('.')[0].TrimEnd(' ').ToUpperInvariant()
            if ($updateStem -in @('CON', 'PRN', 'AUX', 'NUL', 'CONIN$', 'CONOUT$') -or $updateStem -match '^(COM|LPT)[1-9\u00B9\u00B2\u00B3]$') {
                throw 'A payload filename names a Windows device.'
            }
        }
        $updateRootPrefix = [IO.Path]::GetFullPath($Root).TrimEnd('\') + '\'
        $updateResolved = [IO.Path]::GetFullPath([IO.Path]::Combine($Root, $RelativePath.Replace('/', '\')))
        if (-not $updateResolved.StartsWith($updateRootPrefix, [StringComparison]::OrdinalIgnoreCase)) { throw 'A payload path escapes its root.' }
        return $updateResolved
    }

    function Assert-Inventory([string]$Root, [object[]]$Files) {
        Assert-OrdinaryPath $Root
        $updateExpected = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        [long]$updateTotal = 0
        foreach ($updateFile in $Files) {
            $updatePath = Get-PayloadPath $Root ([string]$updateFile.path)
            if (-not $updateExpected.Add([string]$updateFile.path) -or [long]$updateFile.length -lt 0 -or [long]$updateFile.length -gt 536870912
                -or [string]$updateFile.sha256 -notmatch '^[0-9a-f]{64}$') { throw 'The receipt file inventory is invalid.' }
            $updateTotal += [long]$updateFile.length
            if ($updateTotal -gt 2147483648) { throw 'The payload exceeds the expanded size limit.' }
            Assert-OrdinaryPath $updatePath
            if (-not [IO.File]::Exists($updatePath) -or ([IO.FileInfo]::new($updatePath)).Length -ne [long]$updateFile.length
                -or (Get-UpdateHash $updatePath) -ne [string]$updateFile.sha256) { throw 'A payload file changed after verification.' }
        }
        $updateFound = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
        $updatePending = [Collections.Generic.Stack[string]]::new()
        $updatePending.Push($Root)
        $updatePrefix = [IO.Path]::GetFullPath($Root).TrimEnd('\') + '\'
        $updateEntryCount = 0
        while ($updatePending.Count -gt 0) {
            foreach ($updatePath in [IO.Directory]::EnumerateFileSystemEntries($updatePending.Pop())) {
                $updateEntryCount++
                if ($updateEntryCount -gt 16384) { throw 'The payload has too many filesystem entries.' }
                $updateAttributes = [IO.File]::GetAttributes($updatePath)
                if (($updateAttributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw 'The payload contains a filesystem link.' }
                if (($updateAttributes -band [IO.FileAttributes]::Directory) -ne 0) { $updatePending.Push($updatePath) }
                else { [void]$updateFound.Add($updatePath.Substring($updatePrefix.Length).Replace('\', '/')) }
            }
        }
        if (-not $updateFound.SetEquals($updateExpected)) { throw 'The payload file set differs from the receipt.' }
    }

    function Set-LumenShortcut([string]$Executable, [string]$InstallRoot, [string]$PreviousExecutable, [string]$LaunchId) {
        $updatePrograms = [Environment]::GetFolderPath([Environment+SpecialFolder]::Programs)
        if (-not $updatePrograms) { throw 'The current-user Start Menu directory is unavailable.' }
        Assert-OrdinaryPath $updatePrograms
        [void][IO.Directory]::CreateDirectory($updatePrograms)
        $script:updateShortcutPath = [IO.Path]::Combine($updatePrograms, 'Lumen Emby Client.lnk')
        $updateTemporaryShortcut = [IO.Path]::Combine($updatePrograms, '.Lumen Emby Client.' + $LaunchId + '.lnk')
        Assert-OrdinaryPath $script:updateShortcutPath
        Assert-OrdinaryPath $updateTemporaryShortcut
        if ([IO.File]::Exists($updateTemporaryShortcut) -or [IO.Directory]::Exists($updateTemporaryShortcut)) {
            throw 'The temporary shortcut destination already exists.'
        }
        $updateOwnTemporaryShortcut = $false
        $updateShell = New-Object -ComObject WScript.Shell
        $updateOldLink = $null
        $updateNewLink = $null
        $updateOldHash = $null
        try {
            if ([IO.File]::Exists($script:updateShortcutPath)) {
                $updateOldLink = $updateShell.CreateShortcut($script:updateShortcutPath)
                $updateOldTarget = [IO.Path]::GetFullPath([string]$updateOldLink.TargetPath)
                $updateInstalledPrefix = [IO.Path]::GetFullPath($InstallRoot).TrimEnd('\') + '\'
                if (-not $updateOldTarget.Equals($PreviousExecutable, [StringComparison]::OrdinalIgnoreCase)
                    -and -not ($updateOldTarget.StartsWith($updateInstalledPrefix, [StringComparison]::OrdinalIgnoreCase)
                        -and [IO.Path]::GetFileName($updateOldTarget).Equals('EmbyClient.App.exe', [StringComparison]::OrdinalIgnoreCase))) {
                    throw 'An unrelated shortcut already uses the reserved Lumen Start Menu name.'
                }
                $updateOldHash = Get-UpdateHash $script:updateShortcutPath
                $script:updateShortcutBackup = [IO.Path]::Combine($updateStage, 'previous-start-menu-' + $LaunchId + '.lnk')
                Assert-OrdinaryPath $script:updateShortcutBackup
            }
            $updateNewLink = $updateShell.CreateShortcut($updateTemporaryShortcut)
            $updateNewLink.TargetPath = $Executable
            $updateNewLink.Arguments = ''
            $updateNewLink.WorkingDirectory = [IO.Path]::GetDirectoryName($Executable)
            $updateNewLink.IconLocation = [IO.Path]::Combine([IO.Path]::GetDirectoryName($Executable), 'Assets', 'AppIcon.ico') + ',0'
            $updateNewLink.Description = 'Lumen Emby Client'
            $updateNewLink.WindowStyle = 1
            $updateOwnTemporaryShortcut = $true
            $updateNewLink.Save()
            Assert-OrdinaryPath $script:updateShortcutPath
            Assert-OrdinaryPath $updateTemporaryShortcut
            $updateNewHash = Get-UpdateHash $updateTemporaryShortcut
            if ($updateOldHash) {
                if ((Get-UpdateHash $script:updateShortcutPath) -ne $updateOldHash) { throw 'The existing Start Menu shortcut changed during installation.' }
                [IO.File]::Replace($updateTemporaryShortcut, $script:updateShortcutPath, $script:updateShortcutBackup)
            }
            else { [IO.File]::Move($updateTemporaryShortcut, $script:updateShortcutPath) }
            $script:updateShortcutChanged = $true
            $script:updateShortcutHash = $updateNewHash
            Write-UpdateLog ('Start Menu entry: ' + $script:updateShortcutPath)
        }
        finally {
            if ($updateOwnTemporaryShortcut) {
                try {
                    Assert-OrdinaryPath $updateTemporaryShortcut
                    if ([IO.File]::Exists($updateTemporaryShortcut)) { [IO.File]::Delete($updateTemporaryShortcut) }
                }
                catch { Write-UpdateLog ('Temporary shortcut cleanup failed: ' + $updateTemporaryShortcut) }
            }
            if ($updateNewLink) { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($updateNewLink) }
            if ($updateOldLink) { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($updateOldLink) }
            [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($updateShell)
        }
    }

    function Restore-LumenShortcut {
        if (-not $updateShortcutChanged -or -not $updateShortcutHash) { return }
        Assert-OrdinaryPath $updateShortcutPath
        if (-not [IO.File]::Exists($updateShortcutPath) -or (Get-UpdateHash $updateShortcutPath) -ne $updateShortcutHash) {
            Write-UpdateLog 'The shortcut changed externally; its current contents were retained.'
            return
        }
        if ($updateShortcutBackup -and [IO.File]::Exists($updateShortcutBackup)) {
            Assert-OrdinaryPath $updateShortcutBackup
            [IO.File]::Copy($updateShortcutBackup, $updateShortcutPath, $true)
            Write-UpdateLog 'Restored the previous Lumen Start Menu shortcut.'
        }
        else {
            [IO.File]::Delete($updateShortcutPath)
            Write-UpdateLog 'Removed the new shortcut because the new process was not created.'
        }
    }

    try {
        Assert-OrdinaryPath $updateStage
        Assert-OrdinaryPath $PlanPath
        $updatePlanFullPath = [IO.Path]::GetFullPath($PlanPath)
        if (-not [IO.Path]::GetDirectoryName($updatePlanFullPath).Equals($updateStage, [StringComparison]::OrdinalIgnoreCase)
            -or [IO.Path]::GetFileName($updatePlanFullPath) -notmatch '^install-plan-[0-9a-f]{32}\.json$'
            -or ([IO.FileInfo]::new($PlanPath)).Length -gt 4194304) { throw 'The installation plan path or size is invalid.' }
        $updatePlan = [IO.File]::ReadAllText($PlanPath, [Text.Encoding]::UTF8) | ConvertFrom-Json
        if ($updatePlan.schemaVersion -ne 1 -or [string]$updatePlan.launchId -notmatch '^[0-9a-f]{32}$'
            -or -not ([IO.Path]::GetFullPath([string]$updatePlan.stageDirectory)).Equals($updateStage, [StringComparison]::OrdinalIgnoreCase)) {
            throw 'The installation plan is invalid.'
        }
        if (-not $updatePlanFullPath.Equals([IO.Path]::Combine($updateStage, 'install-plan-' + [string]$updatePlan.launchId + '.json'), [StringComparison]::OrdinalIgnoreCase)
            -or -not ([IO.Path]::GetFullPath($PSCommandPath)).Equals([IO.Path]::Combine($updateStage, 'Install-ReleaseUpdate-' + [string]$updatePlan.launchId + '.ps1'), [StringComparison]::OrdinalIgnoreCase)) {
            throw 'The installation plan and helper must belong to the same unique launch attempt.'
        }
        $updatePayload = [IO.Path]::Combine($updateStage, 'payload')
        $updateRoot = [IO.Path]::GetDirectoryName([IO.Path]::GetDirectoryName($updateStage))
        $updateInstallRoot = [IO.Path]::Combine($updateRoot, 'installed')
        $updateInstallDirectory = [IO.Path]::Combine($updateInstallRoot, [IO.Path]::GetFileName($updateStage))
        if (-not $updatePayload.Equals([IO.Path]::GetFullPath([string]$updatePlan.payloadDirectory), [StringComparison]::OrdinalIgnoreCase)
            -or -not $updateInstallRoot.Equals([IO.Path]::GetFullPath([string]$updatePlan.installRoot), [StringComparison]::OrdinalIgnoreCase)
            -or -not $updateInstallDirectory.Equals([IO.Path]::GetFullPath([string]$updatePlan.installDirectory), [StringComparison]::OrdinalIgnoreCase)
            -or [IO.Directory]::Exists($updateInstallDirectory) -or [IO.File]::Exists($updateInstallDirectory)) {
            throw 'The installation destination must be a new owned version directory.'
        }
        Assert-OrdinaryPath $updatePayload
        Assert-OrdinaryPath $updateInstallDirectory
        $updateReceiptPath = [IO.Path]::Combine($updateStage, 'stage-receipt.json')
        if (([IO.FileInfo]::new($updateReceiptPath)).Length -gt 4194304
            -or (Get-UpdateHash $updateReceiptPath) -ne [string]$updatePlan.receiptSha256) { throw 'The stage receipt changed.' }
        $updateReceipt = [IO.File]::ReadAllText($updateReceiptPath, [Text.Encoding]::UTF8) | ConvertFrom-Json
        $updateFiles = @($updateReceipt.files)
        if ($updateReceipt.schemaVersion -ne 1 -or $updateFiles.Count -eq 0 -or $updateFiles.Count -gt 8192) { throw 'The receipt is invalid.' }
        $updatePreviousExecutable = [IO.Path]::GetFullPath([string]$updatePlan.previousExecutable)
        Assert-OrdinaryPath $updatePreviousExecutable
        if (-not [IO.File]::Exists($updatePreviousExecutable)
            -or -not [IO.Path]::GetFileName($updatePreviousExecutable).Equals('EmbyClient.App.exe', [StringComparison]::OrdinalIgnoreCase)) {
            throw 'The previous application path is invalid.'
        }
        $updateCancelPath = [IO.Path]::Combine($updateStage, 'install-cancel-' + [string]$updatePlan.launchId)
        $updateReadyPath = [IO.Path]::Combine($updateStage, 'install-ready-' + [string]$updatePlan.launchId)
        try { $updateParent = [Diagnostics.Process]::GetProcessById([int]$updatePlan.processId) }
        catch [ArgumentException] { $updateParentExited = $true }
        if ($updateParent) {
            # Bind the Process to its OS handle before acknowledging shutdown; a PID can be reused after exit.
            $updateParentHandle = $updateParent.Handle
            if ($updateParentHandle -eq [IntPtr]::Zero -or $updateParent.StartTime.ToUniversalTime().ToString('O') -ne [string]$updatePlan.processStartTimeUtc) {
                throw 'The requesting process identity changed.'
            }
        }
        Assert-OrdinaryPath $updateReadyPath
        Assert-OrdinaryPath ($updateReadyPath + '.tmp')
        Write-UpdateLog 'Installation accepted. Waiting for the requesting application to exit.'
        [IO.File]::WriteAllText($updateReadyPath + '.tmp', [string]$updatePlan.launchId, [Text.UTF8Encoding]::new($false))
        [IO.File]::Move($updateReadyPath + '.tmp', $updateReadyPath)
        if ($updateParent) {
            try {
                $updateWait = [Diagnostics.Stopwatch]::StartNew()
                while (-not $updateParent.WaitForExit(250)) {
                    if ([IO.File]::Exists($updateCancelPath)) { $updateWasCancelled = $true; throw 'Installation was cancelled before shutdown.' }
                    if ($updateWait.Elapsed.TotalSeconds -gt 120) { throw 'The application did not exit; its complete directory was retained.' }
                }
                $updateParentExited = $true
            }
            finally { $updateParent.Dispose(); $updateParent = $null }
        }
        if ([IO.File]::Exists($updateCancelPath)) { $updateWasCancelled = $true; throw 'Installation was cancelled.' }
        Assert-Inventory $updatePayload $updateFiles
        $updateCandidate = $updateInstallDirectory + '.pending-' + [Guid]::NewGuid().ToString('N')
        Assert-OrdinaryPath $updateCandidate
        [void][IO.Directory]::CreateDirectory($updateCandidate)
        foreach ($updateFile in $updateFiles) {
            $updateSource = Get-PayloadPath $updatePayload ([string]$updateFile.path)
            $updateDestination = Get-PayloadPath $updateCandidate ([string]$updateFile.path)
            Assert-OrdinaryPath $updateSource
            Assert-OrdinaryPath $updateDestination
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($updateDestination))
            $updateInput = [IO.File]::OpenRead($updateSource)
            $updateOutput = $null
            try {
                if ($updateInput.Length -ne [long]$updateFile.length) { throw 'The source payload changed during installation.' }
                $updateOutput = [IO.File]::Open($updateDestination, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
                $updateInput.CopyTo($updateOutput, 131072)
                $updateOutput.Flush($true)
            }
            finally {
                if ($updateOutput) { $updateOutput.Dispose() }
                $updateInput.Dispose()
            }
        }
        Assert-Inventory $updateCandidate $updateFiles
        Assert-OrdinaryPath $updateInstallDirectory
        [IO.Directory]::Move($updateCandidate, $updateInstallDirectory)
        $updateExecutable = [IO.Path]::Combine($updateInstallDirectory, 'EmbyClient.App.exe')
        Set-LumenShortcut $updateExecutable $updateInstallRoot $updatePreviousExecutable ([string]$updatePlan.launchId)
        $updateStart = [Diagnostics.ProcessStartInfo]::new()
        $updateStart.FileName = $updateExecutable
        $updateStart.WorkingDirectory = $updateInstallDirectory
        $updateStart.UseShellExecute = $false
        $updateProcess = [Diagnostics.Process]::Start($updateStart)
        if (-not $updateProcess) { throw 'Windows did not create the new application process.' }
        $updateNewProcessCreated = $true
        $updateProcess.Dispose()
        Write-UpdateLog ('Installed complete release and requested activation: ' + $updateInstallDirectory)
        Write-UpdateLog ('Previous complete version retained at: ' + [IO.Path]::GetDirectoryName($updatePreviousExecutable))
        Write-UpdateLog 'Existing portable shortcuts still point to the old application directory. Runtime activation is not verified by this helper.'
        exit 0
    }
    catch {
        $updateFailure = $_.Exception.Message
        try { Write-UpdateLog ('Installation failed: ' + $updateFailure + ' See RECOVERY.txt. Complete previous application files were retained.') }
        catch { }
        if (-not $updateNewProcessCreated) {
            try { Restore-LumenShortcut }
            catch { try { Write-UpdateLog ('Shortcut recovery failed: ' + $_.Exception.Message) } catch { } }
            if (-not $updateWasCancelled -and $updateParentExited -and $updatePreviousExecutable -and [IO.File]::Exists($updatePreviousExecutable)) {
                try {
                    Assert-OrdinaryPath $updatePreviousExecutable
                    $updateRestoreStart = [Diagnostics.ProcessStartInfo]::new()
                    $updateRestoreStart.FileName = $updatePreviousExecutable
                    $updateRestoreStart.WorkingDirectory = [IO.Path]::GetDirectoryName($updatePreviousExecutable)
                    $updateRestoreStart.UseShellExecute = $false
                    $updateRestored = [Diagnostics.Process]::Start($updateRestoreStart)
                    if ($updateRestored) { $updateRestored.Dispose() }
                    Write-UpdateLog 'Requested activation of the previous complete version.'
                }
                catch { try { Write-UpdateLog ('Previous version activation failed: ' + $_.Exception.Message) } catch { } }
            }
        }
        exit 1
    }
    finally {
        if ($updateParent) { $updateParent.Dispose() }
    }
    """;
}
